UPDATE TBL_RESERVATION
   SET STATUS = '03', PAY_STATUS = '03', CANCELLED_AT = SYSDATE, CANCELLED_BY = #{cancelledBy}
 WHERE RESERVATION_ID = #{reservationId} AND STATUS = '01'

mapper.select:
SELECT w.REVIEW_ID, w.RESERVATION_ID, w.RATING, w.CONTENT, w.CREATED_AT, w.REPLY_CONTENT, w.REPLIED_AT, w.ADMIN_ID, m.MEMBER_NAME, m.MEMBER_ID, r.HOUSE_TYPE, r.PACK_TYPE, r.FROM_ADDRESS, r.TO_ADDRESS, v.MOVE_DATE, (SELECT COUNT(*) FROM TBL_RESERVATION v2 JOIN TBL_MOVE_REQUEST r2 ON r2.REQUEST_ID = v2.REQUEST_ID WHERE r2.MEMBER_ID = m.MEMBER_ID AND v2.STATUS = '02' AND v2.MOVE_DATE <= v.MOVE_DATE) AS USAGE_COUNT, (SELECT COUNT(*) FROM TBL_REVIEW_PHOTO p WHERE p.REVIEW_ID = w.REVIEW_ID) AS PHOTO_COUNT, (SELECT MIN(p.FILE_PATH) KEEP (DENSE_RANK FIRST ORDER BY p.SORT_ORDER) FROM TBL_REVIEW_PHOTO p WHERE p.REVIEW_ID = w.REVIEW_ID) AS FIRST_PHOTO FROM TBL_REVIEW w JOIN TBL_RESERVATION v ON v.RESERVATION_ID = w.RESERVATION_ID JOIN TBL_MOVE_REQUEST r ON r.REQUEST_ID = v.REQUEST_ID JOIN TBL_MEMBER m ON m.MEMBER_ID = r.MEMBER_ID
m.MEMBER_ID = #{memberId} AND w.RATING >= #{minRating}
ORDER BY w.CREATED_AT DESC, w.REVIEW_ID DESC
